import CoreGraphics
import Foundation

// Level data as shipped in Resources/levels.json (generated by tools/build_levels.py).
// Coordinates are points, origin bottom-left, y up.

struct WorldInfo: Decodable {
    let name: String
    let subtitle: String
    let neon: String
    let rock: String
    let bgTop: String
    let bgBottom: String
}

struct Pad {
    let x: CGFloat
    let y: CGFloat      // top surface
    let width: CGFloat
}

struct Mine {
    let radius: CGFloat
    let path: [CGPoint]
    let speed: CGFloat
    let loop: Bool
}

struct Spinner {
    let center: CGPoint
    let length: CGFloat
    let arms: Int
    let speed: CGFloat  // radians per second, positive = counter-clockwise
    let phase: CGFloat
}

struct Laser {
    let a: CGPoint
    let b: CGPoint
    let on: Double
    let off: Double
    let phase: Double
}

struct Wind {
    let rect: CGRect
    let force: CGPoint
}

struct KeyItem {
    let position: CGPoint
    let color: Int
}

struct Door {
    let rect: CGRect
    let color: Int
}

struct LevelData {
    let id: Int
    let world: Int
    let name: String
    let hint: String
    let width: CGFloat
    let height: CGFloat
    let fuel: Double
    let par: Double
    let start: Pad
    let goal: Pad
    /// Polygons; each polygon is a list of rings (outer ring first, then holes).
    let terrain: [[[CGPoint]]]
    let stars: [CGPoint]
    let cans: [CGPoint]
    let spikes: [[CGPoint]]
    let mines: [Mine]
    let spinners: [Spinner]
    let lasers: [Laser]
    let winds: [Wind]
    let keys: [KeyItem]
    let doors: [Door]
}

struct LevelLibrary {
    let worlds: [WorldInfo]
    let levels: [LevelData]

    static let empty = LevelLibrary(worlds: [], levels: [])

    static func load(bundle: Bundle = .main) -> LevelLibrary {
        guard let url = bundle.url(forResource: "levels", withExtension: "json"),
              let data = try? Data(contentsOf: url) else {
            return .empty
        }
        return (try? decode(data)) ?? .empty
    }

    static func decode(_ data: Data) throws -> LevelLibrary {
        let file = try JSONDecoder().decode(RawFile.self, from: data)
        return LevelLibrary(worlds: file.worlds, levels: file.levels.map { $0.level })
    }
}

// MARK: - Raw JSON mirror

private struct RawFile: Decodable {
    let version: Int
    let worlds: [WorldInfo]
    let levels: [RawLevel]
}

private struct RawMine: Decodable {
    let r: CGFloat
    let path: [[CGFloat]]
    let speed: CGFloat
    let loop: Bool
}

private struct RawSpinner: Decodable {
    let c: [CGFloat]
    let len: CGFloat
    let arms: Int
    let speed: CGFloat
    let phase: CGFloat
}

private struct RawLaser: Decodable {
    let a: [CGFloat]
    let b: [CGFloat]
    let on: Double
    let off: Double
    let phase: Double
}

private struct RawWind: Decodable {
    let rect: [CGFloat]
    let force: [CGFloat]
}

private struct RawKey: Decodable {
    let p: [CGFloat]
    let color: Int
}

private struct RawDoor: Decodable {
    let rect: [CGFloat]
    let color: Int
}

private func makeRect(_ a: [CGFloat]) -> CGRect {
    guard a.count >= 4 else { return .zero }
    return CGRect(x: a[0], y: a[1], width: a[2], height: a[3])
}

private func makePad(_ a: [CGFloat]) -> Pad {
    Pad(x: a.count > 0 ? a[0] : 0, y: a.count > 1 ? a[1] : 0, width: a.count > 2 ? a[2] : 64)
}

private struct RawLevel: Decodable {
    let id: Int
    let world: Int
    let name: String
    let hint: String
    let size: [CGFloat]
    let fuel: Double
    let par: Double
    let start: [CGFloat]
    let goal: [CGFloat]
    let terrain: [[[[CGFloat]]]]
    let stars: [[CGFloat]]
    let cans: [[CGFloat]]
    let spikes: [[[CGFloat]]]
    let mines: [RawMine]
    let spinners: [RawSpinner]
    let lasers: [RawLaser]
    let winds: [RawWind]
    let keys: [RawKey]
    let doors: [RawDoor]

    var level: LevelData {
        LevelData(
            id: id,
            world: world,
            name: name,
            hint: hint,
            width: size.count > 0 ? size[0] : 420,
            height: size.count > 1 ? size[1] : 1000,
            fuel: fuel,
            par: par,
            start: makePad(start),
            goal: makePad(goal),
            terrain: terrain.map { poly in poly.map { ring in ring.map { CGPoint($0) } } },
            stars: stars.map { CGPoint($0) },
            cans: cans.map { CGPoint($0) },
            spikes: spikes.map { tri in tri.map { CGPoint($0) } },
            mines: mines.map { Mine(radius: $0.r, path: $0.path.map { CGPoint($0) }, speed: $0.speed, loop: $0.loop) },
            spinners: spinners.map {
                Spinner(center: CGPoint($0.c), length: $0.len, arms: max(1, $0.arms), speed: $0.speed, phase: $0.phase)
            },
            lasers: lasers.map { Laser(a: CGPoint($0.a), b: CGPoint($0.b), on: $0.on, off: $0.off, phase: $0.phase) },
            winds: winds.map { Wind(rect: makeRect($0.rect), force: CGPoint($0.force)) },
            keys: keys.map { KeyItem(position: CGPoint($0.p), color: $0.color) },
            doors: doors.map { Door(rect: makeRect($0.rect), color: $0.color) }
        )
    }
}
